def split_array(nums, k):
    def subarrays_needed(limit):
        count, current = 1, 0
        for num in nums:
            if current + num > limit:
                count += 1
                current = 0
            current += num
        return count

    lo, hi = max(nums), sum(nums)

    while lo < hi:
        mid = (lo + hi) // 2
        if subarrays_needed(mid) <= k:
            hi = mid
        else:
            lo = mid + 1

    return lo

